/*  JustPlayMusic  A minimalist Mac Application that showcases the library files needed to play  a background .mid standard MIDI file.     Usage in your own project:  Just #include "muMIDIPlay.c" in your project, and that file will include the rest    Step 1a: either have a .mid file in the same folder as the executable  Step 1b: or embed the .mid file in a 'smf ' raw data resource in your project's .rsrc file    Step 2: Use this every time you want to load a standard MIDI file     prepMIDIFileForPlay("name of file"); //from a file in the same directory       or     prepMIDIResForPlay(resID); //from a 'smf ' resource embedded in your application  this will copy the content of the .mid into memory    Step 3: Once during your loop pass, do this:     midiLoopPass()  returns false if it's done playing. You can also check it with isMIDIDone()    Step 4: Do this to "rewind" the midi file at its beginning and start the playback over     rewindAndPlayMIDI();*///Includes#include "muMidiPlay.c"  //one-stop shop include#include "HideMenuBar.c" //very useful to tag along game projects#include "myWindow.c"    //really simple window setup//Defines#define kEmbedded_Warcraft 128 //this is the 'smf ' ID for human2.mid embedded in a resource#define kEmbedded_Bach     129 //this is the 'smf ' ID for Bach's toccata & fugue in a resource//Functionsvoid main()	{	Boolean isPlaying = false; //very basic loop control for playback		myInitStuff(); //Mac Manager standard stuff	hideMenuBar(); //from HideMenuBar.c		/*********** * CHOICE #1* Select which window you want for this demo program***********/	//myWindow(true);       //if true, sets simple window with PICT	myWindow(false);		//if false, sets a white plain window with text instruction to quit   /***********/		setupMIDISerial(true); //must massage the serial port. true=modem, false=printer	/*********** * CHOICE #2* Select which loading method for the midi data***********/	//prepMIDIResForPlay(kEmbedded_Bach);  //load from 'smf ' data resource embedded in this app	prepMIDIFileForPlay("\pcanyon.mid");   //load from a file in the same dir as this app/***********/		isPlaying = true; //prepare the loop control	while(isPlaying) //main loop		{		if(midiLoopPass() == false) //if false, then no more MIDI events left to play			{			rewindAndPlayMIDI();			}		if(Button()) 			{			allNotesOff();				isPlaying = false; //one possible way to exit out of the loop			}		}	showMenuBar(); //from HideMenuBar.c		closeSerialDriver(); //must be done once at the end	}